    # as one object when the bounding box is compact, then move toward nearest edge.
    colors = {v for row in grid for v in row if v}
    out = [[0] * w for _ in range(h)]
    for color in colors:
        pts = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == color]
        # Each color can encode separated objects; keep pieces individually connected.
        unseen=set(pts)
        while unseen:
            seed=unseen.pop(); comp={seed}; stack=[seed]
            while stack:
                r,c=stack.pop()
                for p in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                    if p in unseen: unseen.remove(p); comp.add(p); stack.append(p)
            minr=min(r for r,c in comp); maxr=max(r for r,c in comp)
            if (minr+maxr)/2 < h/2: dr=-minr
